const busy=ref(false), error=ref(''), success=ref(''), search=ref(''), areaFilter=ref(''), form=ref<Row|null>(null), formType=ref(''), selectedNode=ref<Row|null>(null), selectedOrder=ref<Row|null>(null), selectedRun=ref<Row|null>(null), history=ref<Row[]>([]), historyMetric=ref('methane'), historyHours=ref(24), historyFrom=ref(''), historyTo=ref(''), reportFrom=ref(''), reportTo=ref(''), reportArea=ref(''), simulationRunning=ref(false)
watch(tab,value=>{search.value='';nodeTools.value=false;selectedOrder.value=null;selectedNode.value=null;userMenu.value=false;noticeMenu.value=false;if(route.path!=='/'+value)router.replace('/'+value)})
watch(()=>route.path,value=>{tab.value=value.slice(1)||'overview'})
const locatedNode=ref<number|null>(null),clockNow=ref(Date.now()),nodeTools=ref(false),assigneeSearch=ref('')
const dispatchAreas=computed(()=>form.value?dispatchAreaIds(form.value.orderIds||[form.value.id],orders.value,nodes.value):null)
