const sectionFilter=ref(''),nodeStatus=ref('全部状态'),nodePage=ref(1),pageSize=ref(20),orderPage=ref(1),orderFilter=ref('ALL'),selectedIds=ref<number[]>([]),sortDirection=ref(1),hoverNode=ref<number|null>(null),auditActor=ref(''),auditAction=ref(''),auditFrom=ref(''),auditTo=ref(''),selectedAudit=ref<Row|null>(null),nodeThresholds=ref<Row>({}),nodeRuleSettings=ref<Row>({}),lastUpdate=ref<Date|null>(null),profile=ref<Row>({}),settingTab=ref('基本信息'),passwordForm=ref<Row|null>(null)
useOverlayScrollLock(()=>!!(form.value||selectedNode.value||selectedAudit.value||selectedRun.value))
