const visibleOrders=computed(()=>orders.value.filter(o=>(orderFilter.value==='ALL'||(orderFilter.value==='PROCESSING'?['PROCESSING','ACCEPTED'].includes(o.status):o.status===orderFilter.value))&&`${orderNumber(o)}${o.title}${o.node_code}${o.assignee_name||''}${statusName[o.status]}`.toLowerCase().includes(search.value.toLowerCase())))
