const alertedNotifications=new Set<number>();let alertsInitialized=false
function notifyNewMessages(){
 const prefs=profile.value.preferences||{},time=new Date()
 const fresh=visibleNotifications.value.filter(n=>!n.is_read&&!alertedNotifications.has(n.id)&&shouldAlertNotification(n,alarms.value,prefs,time));notifications.value.forEach(n=>alertedNotifications.add(n.id))
 if(!alertsInitialized){alertsInitialized=true;return}if(isDemo||!fresh.length)return
 if(prefs.sound){try{const audio=new AudioContext(),oscillator=audio.createOscillator(),gain=audio.createGain();oscillator.frequency.value=740;gain.gain.setValueAtTime(.08,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.3);oscillator.connect(gain);gain.connect(audio.destination);oscillator.start();oscillator.stop(audio.currentTime+.3);oscillator.onended=()=>{void audio.close()}}catch{}}
 if(prefs.desktop&&'Notification' in window&&Notification.permission==='granted')for(const n of fresh.slice(0,3))new Notification(n.title,{body:displayMessage(n.content),tag:'nephh-'+n.id})
}
