const chart=computed(()=>{const values=[...history.value].reverse().map(r=>Number(r.metric_value));if(!values.length)return '';const min=Math.min(...values),max=Math.max(...values),span=max-min||1;return values.map((v,i)=>`${20+i/(Math.max(values.length-1,1))*760},${160-(v-min)/span*130}`).join(' ')})
function format(value: any){return value?new Date(value).toLocaleString('zh-CN'):'—'}
function displayMessage(value:unknown){return String(value??'').replaceAll('超过演示阈值','超过配置阈值')}
function auditTimestamp(value:any){if(!value)return '—';const date=new Date(value);if(Number.isNaN(date.getTime()))return '—';const pad=(n:number)=>String(n).padStart(2,'0');return `${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`}
function nodeState(n:Row){if(!n.enabled)return '停用';if(n.maintenance)return '维护';if(!n.last_seen)return '无数据';const time=parseTelemetryTime(n.last_seen);if(time===null||time-clockNow.value>60000)return '时间未知';if(clockNow.value-time>reportTimeoutMs(n.report_seconds))return '离线';return n.active_alarms?'告警':'正常'}
function nodeDisplayState(n:Row){return nodeState(n)==='正常'?'无活动告警':nodeState(n)}
function latest(n:Row,metric:string){const row=n.latest?.find((r:Row)=>r.metric===metric);return row?`${row.metric_value} ${row.unit}`:'—'}
