 if(!form.value&&selectedOrder.value){const id=selectedOrder.value.id;const result=await request(`/orders/${id}`);if(selectedOrder.value?.id===id)selectedOrder.value=result}
 if(!form.value&&selectedRun.value){const id=selectedRun.value.id;const result=await request(`/patrol/runs/${id}`);if(selectedRun.value?.id===id)selectedRun.value=result}
}
async function refreshLive(){
 if(disposed||document.hidden)return
 if(refreshingLive||loadingData||busy.value){livePending=true;return}
 refreshingLive=true;livePending=false
 const version=dataVersion
 try{
  if(Date.now()-lastFullRefresh>=15000&&!form.value){await load();lastFullRefresh=Date.now()}
  else{
   const result=await Promise.all([request<Row[]>('/nodes'),request<Row[]>('/alarms'),request<Row[]>('/notifications'),request<Row[]>('/orders')])
   if(disposed||version!==dataVersion||busy.value)return
   ;[nodes.value,alarms.value,notifications.value,orders.value]=result
   lastUpdate.value=new Date();notifyNewMessages()
  }
  if(!disposed&&!busy.value)await refreshDetails()
  liveError.value=''
 }catch(e){if(!disposed)liveError.value=e instanceof Error?e.message:'实时更新失败'}
 finally{refreshingLive=false;if(livePending&&!disposed&&!loadingData&&!busy.value){livePending=false;void refreshLive()}}
}
function resumeLive(){if(!document.hidden)void refreshLive()}

async function save(){await act(async()=>{
 const f=form.value!;let path='',method='POST',body:Row={...f}
 switch(formType.value){
 case 'user':path='/users';break
 case 'editUser':path=`/users/${f.id}`;method='PUT';body={...f,role:f.role,areas:f.areas.map(Number)};break
 case 'password':path=`/users/${f.id}/password`;break
 case 'corridor':path=f.id?`/corridors/${f.id}`:'/corridors';method=f.id?'PUT':'POST';break
 case 'area':path=f.id?`/areas/${f.id}`:'/areas';method=f.id?'PUT':'POST';break
 case 'section':path=f.id?`/sections/${f.id}`:'/sections';method=f.id?'PUT':'POST';body.areaId=Number(f.areaId);break
 case 'node':path='/nodes';body.areaId=Number(f.areaId);break
 case 'editNode':path=`/nodes/${f.id}`;method='PUT';body.metrics=f.metricList.join(',');break
 case 'rule':path='/rules';body.areaId=Number(f.areaId);body.threshold=Number(f.threshold);body.durationSeconds=Number(f.durationSeconds);break
 case 'order':path='/orders';body.nodeId=Number(f.nodeId);break
 case 'schedule':path=`/orders/${f.id}/schedule`;body.dueAt=f.dueAt?new Date(f.dueAt).toISOString():null;break
 case 'assign':body.participantIds=f.participantIds||[Number(f.assigneeId)];if(!validDispatchCrew(users.value,dispatchAreaIds(f.orderIds||[f.id],orders.value,nodes.value)||[],body.participantIds))throw new Error('请选择对全部所选工单区域都有授权的1至2位巡检员；无共同人选时请按区域拆批');body.note=f.note||'请按工单要求处理并提交现场记录';body.assigneeId=Number(body.participantIds[0]);path=f.orderIds?.length?'/orders/batch-assign':`/orders/${f.id}/assign`;body.dueAt=f.dueAt?new Date(f.dueAt).toISOString():null;break
 case 'ack':path=`/alarms/${f.id}/acknowledge`;break
 case 'action':path=`/orders/${f.id}/action`;break
 case 'handbook':path=f.id?`/handbooks/${f.id}`:'/handbooks';method=f.id?'PUT':'POST';break
 case 'plan':path='/patrol/plans';body={...f,areaId:Number(f.areaId),assigneeId:Number(f.assigneeId),periodHours:Number(f.periodHours),points:f.nodeIds.map((nodeId:string)=>({nodeId:Number(nodeId),checkItems:f.checkItems}))};break
 case 'patrolResult':path=`/patrol/results/${f.id}`;break
 }
 if(!path)throw new Error('未知操作');await request(path,method,body);await load();if(selectedOrder.value)selectedOrder.value=await request(`/orders/${selectedOrder.value.id}`);if(selectedRun.value)selectedRun.value=await request(`/patrol/runs/${selectedRun.value.id}`);form.value=null;selectedIds.value=[]
},formType.value==='assign'?'已派给 '+(form.value?.participantIds||[]).map((id:number)=>users.value.find(u=>u.id===id)?.display_name||users.value.find(u=>u.id===id)?.username).join('、')+'，等待接单':'保存成功')}
async function editNode(n:Row){await act(async()=>{sections.value=await request(`/sections?areaId=${n.area_id}`)});open('editNode',{...n,reportSeconds:n.report_seconds,externalId:n.external_id,x:n.x_position,y:n.y_position,sectionId:n.section_id,ownerId:n.owner_id,metricList:n.metrics?.split(',')||['methane','temperature','humidity','infrared']})}
