async function remove(path:string,label:string){if(!window.confirm(`确定删除${label}？已有业务关联时无法删除，可改为停用。`))return;await act(async()=>{await request(path,'DELETE');await load();if(tab.value==='areas')sections.value=await request(`/sections?areaId=${areaFilter.value||areas.value[0]?.id}`)})}
async function showNode(n:Row){selectedNode.value=n;historyMetric.value='all';historyFrom.value='';historyTo.value='';await loadHistory();if(['ADMIN','MANAGER'].includes(identity.value.role)){try{const rows=await request<Row[]>(`/rules?areaId=${n.area_id}`);nodeThresholds.value=Object.fromEntries(rows.map(r=>[r.metric,r.threshold_value]));nodeRuleSettings.value=Object.fromEntries(rows.map(r=>[r.metric,r]))}catch{nodeThresholds.value={};nodeRuleSettings.value={}}}}
let historyRequestId=0
async function loadHistory(quiet=false){
 if(!selectedNode.value)return
 const nodeId=selectedNode.value.id,requestId=++historyRequestId
 const q=new URLSearchParams({hours:String(historyHours.value)})
 if(historyMetric.value!=='all')q.set('metric',historyMetric.value)
 if(historyFrom.value)q.set('from',new Date(historyFrom.value).toISOString())
 if(historyTo.value)q.set('to',new Date(historyTo.value).toISOString())
 const work=async()=>{const result=await request<Row[]>(`/nodes/${nodeId}/history?${q}`);if(requestId===historyRequestId&&selectedNode.value?.id===nodeId)history.value=result}
 if(quiet)await work();else await act(work)
}
