function reportQuery(){const q=new URLSearchParams();if(reportArea.value)q.set('areaId',reportArea.value);if(reportFrom.value)q.set('from',new Date(reportFrom.value).toISOString());if(reportTo.value)q.set('to',new Date(reportTo.value).toISOString());return '?'+q.toString()}
async function refreshStats(){await act(async()=>{stats.value=await request('/statistics'+reportQuery())})}
async function exportReport(type:string){await act(async()=>{const rows=await request<Row[]>('/reports'+reportQuery()+'&type='+type);exportCsv(rows,type==='orders'?'巡检工单报表':'巡检告警报表')})}
async function showRules(){await act(async()=>{rules.value=await request(`/rules?areaId=${areaFilter.value||areas.value[0]?.id}`)});tab.value='rules'}
function exportCsv(rows:Row[],name:string){if(!rows.length){error.value='没有可导出的数据';return}const keys=Object.keys(rows[0]!);const cell=(v:unknown)=>{let s=typeof v==='object'?JSON.stringify(v):String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};const blob=new Blob(['\ufeff'+[keys.map(cell).join(','),...rows.map(r=>keys.map(k=>cell(r[k])).join(','))].join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name+'.csv';a.click();URL.revokeObjectURL(url)}
let lastActivity=Date.now()
function activity(){lastActivity=Date.now()}
function keyShortcut(e:KeyboardEvent){activity();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.querySelector<HTMLInputElement>('.d-global-search input')?.focus()}if(e.key==='Escape'){if(window.matchMedia('(max-width:900px)').matches)navigationCollapsed.value=true;nodeTools.value=false;selectedNode.value=null;selectedAudit.value=null;form.value=null;userMenu.value=false;noticeMenu.value=false;moreMenu.value=false}}
let secondTimer:ReturnType<typeof setInterval>|undefined
let timer:ReturnType<typeof setInterval>|undefined
onMounted(()=>{
 secondTimer=setInterval(()=>{clockNow.value=Date.now()},1000)
 window.addEventListener('pointerdown',activity,{passive:true});window.addEventListener('keydown',keyShortcut);window.addEventListener('wheel',activity,{passive:true})
 window.addEventListener('nephh:telemetry-saved',resumeLive);window.addEventListener('focus',resumeLive);document.addEventListener('visibilitychange',resumeLive)
 void refresh()
 timer=setInterval(async()=>{
  if(!isDemo&&Date.now()-lastActivity>(profile.value.idleMinutes||30)*60000){try{if(profile.value.sessionId)await request(`/sessions/${profile.value.sessionId}/revoke`,'POST')}finally{void logout()}return}
  if(simulationRunning.value&&manager.value&&!busy.value&&!form.value&&!refreshingLive&&!loadingData){await act(async()=>{for(const n of visibleNodes.value.filter(n=>n.enabled&&!n.maintenance))await request(`/nodes/${n.id}/simulate`,'POST',{scenario:'normal'})})}
  void refreshLive()
 },2000)
})
onUnmounted(()=>{
 disposed=true;historyRequestId++
 if(secondTimer)clearInterval(secondTimer);if(timer)clearInterval(timer)
 window.removeEventListener('pointerdown',activity);window.removeEventListener('keydown',keyShortcut);window.removeEventListener('wheel',activity)
 window.removeEventListener('nephh:telemetry-saved',resumeLive);window.removeEventListener('focus',resumeLive);document.removeEventListener('visibilitychange',resumeLive)
 if(profile.value.avatarBlob)URL.revokeObjectURL(profile.value.avatarBlob)
})
async function logout(){try{if(!isDemo&&profile.value.sessionId)await request('/sessions/'+profile.value.sessionId+'/revoke','POST')}catch{}finally{clearSession();router.push('/login')}}

const titleMap:Row={overview:'总览',nodes:'节点管理',orders:'工单管理',audit:'审计日志',statistics:'报表',settings:'个人设置',alarms:'告警中心',patrol:'巡检计划',handbooks:'处置手册',notifications:'消息通知',users:'用户权限',areas:'管廊与区域',rules:'告警规则',simulator:'数据联调控制台'}
