const pageTitle=computed(()=>selectedOrder.value?'工单详情':titleMap[tab.value]||'业务管理')
const displayName=computed(()=>profile.value.displayName||identity.value.displayName||identity.value.username||'用户')
const pagedNodes=computed(()=>visibleNodes.value.slice((nodePage.value-1)*pageSize.value,nodePage.value*pageSize.value))
const pagedOrders=computed(()=>visibleOrders.value.slice((orderPage.value-1)*pageSize.value,orderPage.value*pageSize.value))
const zoneNodes=computed(()=>nodes.value.filter(n=>!areaFilter.value||String(n.area_id)===areaFilter.value))
const zoneAlarms=computed(()=>alarms.value.filter(a=>zoneNodes.value.some(n=>n.id===a.node_id)))
const offlineCount=computed(()=>zoneNodes.value.filter(n=>nodeState(n)==='离线').length)
const todayAlarms=computed(()=>zoneAlarms.value.filter(a=>!a.eventOnly&&new Date(a.triggered_at).toDateString()===new Date().toDateString()))
const onlineCount=computed(()=>zoneNodes.value.filter(n=>!['离线','停用','无数据','时间未知'].includes(nodeState(n))).length)
const boardColumns=[{status:'DRAFT',name:'待派发',color:'amber'},{status:'ASSIGNED',name:'待接单',color:'blue'},{status:'PROCESSING',name:'处理中',color:'blue'},{status:'REVIEW',name:'待复核',color:'teal'}]
const visibleAudits=computed(()=>audits.value.filter(a=>(!auditActor.value||a.actor_name===auditActor.value)&&(!auditAction.value||a.action===auditAction.value)&&(!auditFrom.value||new Date(a.created_at)>=new Date(auditFrom.value))&&(!auditTo.value||new Date(a.created_at)<=new Date(auditTo.value+'T23:59:59.999'))&&`${a.actor_name}${a.object_type}${a.object_id}`.includes(search.value)))
const actionLabels:Row={SIMULATE:'更新节点读数',CREATE:'创建工单',ASSIGN:'派发工单',ACCEPT:'接收工单',START:'开始处理',SUBMIT:'提交复核',APPROVE:'复核完成',REJECT:'退回重做',CANCEL:'取消工单',UPDATE:'修改配置',UPDATE_SCHEDULE:'调整截止时间',ACKNOWLEDGE:'确认告警',UPLOAD:'上传照片',RESET_PASSWORD:'重置密码',CHECK:'点位检查',GENERATE:'生成巡检任务',TOGGLE:'调整启用状态'}
const navItems=computed(()=>{
 const icons:Record<string,string>={overview:'grid',nodes:'nodes',alarms:'warning',orders:'orders',patrol:'check',handbooks:'shield',notifications:'bell',statistics:'chart',audit:'history',users:'user'}
 if(viewRole.value==='supervisor')return [{key:'statistics',name:'报表',icon:'chart',group:'统计与追溯'},{key:'audit',name:'审计日志',icon:'history',group:'统计与追溯'}]
 return navigation.value.map(n=>({key:n.key,name:n.key==='orders'&&identity.value.role==='INSPECTOR'?'我的工单':n.key==='patrol'&&identity.value.role==='INSPECTOR'?'我的巡检':titleMap[n.key]||n.name,icon:icons[n.key]||'grid',group:['statistics','audit'].includes(n.key)?'统计与追溯':n.key==='users'?'管理配置':'运行作业'}))
})
function navigateWorkspace(key:string){tab.value=key;closeDetails();if(window.matchMedia('(max-width:900px)').matches)navigationCollapsed.value=true}
watch(areaFilter,()=>{sectionFilter.value=''})
watch([search,nodeStatus,areaFilter,sectionFilter],()=>{nodePage.value=1;hoverNode.value=null;locatedNode.value=null})
watch([search,orderFilter],()=>{orderPage.value=1;selectedIds.value=[]})
watch(takeMode,value=>localStorage.setItem('nephh-take-mode',String(value)))
watch(success,value=>{if(value)setTimeout(()=>success.value='',3200)})
function health(n:Row){if(!isDemo)return 0;if(n.health!==undefined)return n.health;if(['离线','无数据','停用','时间未知'].includes(nodeState(n)))return 0;return Math.max(0,Math.min(100,Math.round(100-numeric(n,'methane')*.8-Math.max(0,numeric(n,'temperature')-25)*.5)))}
function healthText(n:Row){return isDemo?String(health(n)):'—'}
function numeric(n:Row,metric:string){return Number(visibleMetric(n,metric,isDemo,clockNow.value)?.metric_value||0)}
function reading(n:Row,metric:string){return ['无数据','停用','时间未知'].includes(nodeState(n))?'—':String(visibleMetric(n,metric,isDemo,clockNow.value)?.metric_value??'—')}
function orderNumber(o:Row){return o.number||`WO-${new Date(o.created_at).toISOString().slice(2,10).replaceAll('-','')}-${String(o.id).padStart(3,'0')}`}
function due(o:Row){if(!o.due_at)return '未设置';const d=new Date(o.due_at),delta=d.getTime()-Date.now();if(delta<0)return '已超时 '+Math.ceil(-delta/60000)+'分钟';if(delta<3600000)return Math.ceil(delta/60000)+'分钟内';return (d.toDateString()===new Date().toDateString()?'今天 ':d.toLocaleDateString('zh-CN')+' ')+d.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}
function countdown(o:Row){if(!o.due_at)return due(o);const remaining=Math.max(0,Math.floor((new Date(o.due_at).getTime()-clockNow.value)/1000));return remaining>3600?due(o):String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0')}
function orderOverdue(o:Row){return o.status==='ASSIGNED'&&o.due_at&&new Date(o.due_at).getTime()<clockNow.value}
function boardOrders(status:string){return orders.value.filter(o=>status==='PROCESSING'?['PROCESSING','ACCEPTED'].includes(o.status):o.status===status)}
function reportAge(value:any){const time=parseTelemetryTime(value);if(time===null)return '时间待确认';if(time-clockNow.value>60000)return '采样时钟异常';const seconds=Math.max(0,Math.floor((clockNow.value-time)/1000));return seconds<10?'刚刚':seconds<60?seconds+'秒前':seconds<3600?Math.floor(seconds/60)+'分钟前':Math.floor(seconds/3600)+'小时前'}
function relativeTime(value:any){const minutes=Math.floor((clockNow.value-new Date(value).getTime())/60000);return minutes<1?'刚刚':minutes<60?minutes+'分钟前':Math.floor(minutes/60)+'小时前'}
function shortTime(value:any){return value?new Date(value).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}):'—'}
function backToOrders(){selectedOrder.value=null;window.scrollTo(0,0)}
function closeDetails(){selectedOrder.value=null;selectedNode.value=null;selectedAudit.value=null}
function assignOrder(o:Row){const areaId=Number(o.area_id??nodes.value.find(n=>n.id===o.node_id)?.area_id);const eligibleIds=new Set(eligibleDispatchWorkers(users.value,[areaId]).map(u=>u.id));const previous=o.participant_ids?.length?[...o.participant_ids]:o.assignee_id?[o.assignee_id]:[];assigneeSearch.value='';open('assign',{id:o.id,number:orderNumber(o),node_code:o.node_code,areaId,priority:o.priority,note:'',participantIds:previous.filter((id:number)=>eligibleIds.has(id)),dueAt:new Date(Date.now()+1800000).toISOString(),quickDue:'30'})}
async function locateNode(id:number){const node=nodes.value.find(n=>n.id===id);if(!node)return;areaFilter.value=String(node.area_id);sectionFilter.value='';nodeStatus.value='全部状态';search.value='';tab.value='nodes';await nextTick();locatedNode.value=id;nodePage.value=Math.max(1,Math.ceil((visibleNodes.value.findIndex(n=>n.id===id)+1)/pageSize.value))}
function togglePerson(id:number){const f=form.value!;if(f.participantIds.includes(id))f.participantIds=f.participantIds.filter((v:number)=>v!==id);else if(f.participantIds.length<2&&eligibleDispatchWorkers(users.value,dispatchAreas.value||[]).some(u=>u.id===id))f.participantIds.push(id)}
function assignBatchOrders(){const ids=[...selectedIds.value],first=orders.value.find(o=>o.id===ids[0]);assigneeSearch.value='';open('assign',{id:ids[0],orderIds:ids,number:'',node_code:'所选工单共同授权范围',priority:first?.priority||'MEDIUM',note:'',participantIds:[],dueAt:new Date(Date.now()+1800000).toISOString(),quickDue:'30'})}
function profileRole(role:string){if(role==='manager')viewRole.value='manager';else if(role==='supervisor'&&['ADMIN','MANAGER'].includes(identity.value.role)){viewRole.value='supervisor';tab.value='statistics'}else {viewRole.value='readonly';tab.value='overview'};roleMenu.value=false;userMenu.value=false}
function auditObjectLabel(a:Row){if(a.object_type!=='ORDER')return a.object_id;const order=orders.value.find(o=>String(o.id)===String(a.object_id));return order?orderNumber(order):'WO-'+a.object_id}
function selectAllOrders(checked:boolean){selectedIds.value=checked?pagedOrders.value.filter(o=>!['COMPLETED','CANCELLED','REVIEW'].includes(o.status)).map(o=>o.id):[]}
function points(metric:string){const samples=history.value.filter(r=>r.metric===metric).sort((a,b)=>new Date(a.collected_at).getTime()-new Date(b.collected_at).getTime());return samples.map((r,i)=>`${34+i/Math.max(samples.length-1,1)*402},${186-Math.min(100,Math.max(0,Number(r.metric_value)))*1.6}`).join(' ')}
async function saveThresholds(){if(!selectedNode.value)return;await act(async()=>{for(const metric of ['methane','temperature','humidity'])if(nodeThresholds.value[metric]!==undefined)await request('/rules','POST',{areaId:selectedNode.value!.area_id,metric,threshold:Number(nodeThresholds.value[metric]),durationSeconds:nodeRuleSettings.value[metric]?.duration_seconds??0,severity:nodeRuleSettings.value[metric]?.severity||'HIGH',enabled:nodeRuleSettings.value[metric]?.enabled??true});await load()},'阈值已保存')}
async function loadProfile(){try{const result=await request<Row>('/profile');if(result.avatar&&profile.value.avatarBlob)result.avatarBlob=profile.value.avatarBlob;else if(result.avatar&&!isDemo){const response=await fetch('/api/business/profile/avatar',{headers:{Authorization:'Bearer '+sessionStorage.getItem(tokenKey)}});if(response.ok)result.avatarBlob=URL.createObjectURL(await response.blob())}profile.value=result}catch{profile.value={displayName:identity.value.username,role:identity.value.role,phone:'',email:''}}}
watch(tab,value=>{if(value==='settings')loadProfile()})

</script>

<template>
<div class="work-app design-app" :class="{'nav-collapsed':navigationCollapsed}">
 <WorkspaceNavigation :items="navItems" :active="tab" :collapsed="navigationCollapsed" :inert="busy" @toggle="navigationCollapsed=!navigationCollapsed" @navigate="navigateWorkspace" @settings="navigateWorkspace('settings')"/>
 <header class="d-topbar"><div class="d-breadcrumb"><b>智巡管廊</b><span>/</span>{{titleMap[tab]||pageTitle}}</div><div class="d-header-actions"><label class="operations-area"><span>业务区域</span><select v-model="areaFilter" aria-label="业务区域"><option value="">全部授权区域</option><option v-for="a in areas" :key="a.id" :value="String(a.id)">{{a.name}}</option></select></label><span class="d-connection" :title="isDemo?'平台预览':'后端数据连接'"><i class="dot" :class="{gray:liveError||!lastUpdate}"></i>{{isDemo?'演示模式':liveError?'接口连接异常':lastUpdate?'业务接口已连接':'等待接口响应'}}</span><label v-if="isDemo" class="d-take-mode">演示偏好<button class="d-switch" :class="{on:takeMode}" type="button" role="switch" :aria-checked="takeMode" aria-label="抢单模式" @click="takeMode=!takeMode"><i></i></button></label><div class="d-global-search"><Icon name="search"/><input v-model="search" placeholder="搜索节点编号或区域..." aria-label="全局搜索"/><kbd>⌘ K</kbd></div><button class="d-notice" aria-label="消息通知" @click="noticeMenu=!noticeMenu;userMenu=false"><Icon name="bell"/><sup v-if="unread">{{unread>99?'99+':unread}}</sup></button><span v-if="viewRole==='readonly'" class="d-pill blue">只读模式</span><button class="d-user" aria-label="用户菜单" @click="userMenu=!userMenu;noticeMenu=false"><span class="d-avatar"><img v-if="profile.avatarBlob" :src="profile.avatarBlob" alt="个人头像"/><template v-else>{{displayName.slice(0,1)}}</template></span><span><b>{{displayName}}</b><small>{{viewRole==='readonly'?'只读':viewRole==='supervisor'?'运维主管':roleName[identity.role]}}</small></span><Icon name="chevron"/></button></div>
 <div v-if="userMenu" class="d-user-menu"><button @click="tab='settings';settingTab='基本信息';userMenu=false"><Icon name="user"/>个人信息</button><button @click="roleMenu=!roleMenu"><Icon name="refresh"/>切换角色<Icon name="arrow" class="push"/></button><div v-if="roleMenu" class="d-role-list"><button v-for="r in [{key:'manager',name:'值班长'},{key:'supervisor',name:'运维主管'},{key:'readonly',name:'只读'}]" :class="{chosen:viewRole===r.key}" :disabled="r.key!=='readonly'&&!['ADMIN','MANAGER'].includes(identity.role)" @click="profileRole(r.key)"><i class="dot"></i>{{r.name}}<Icon v-if="viewRole===r.key" class="push" name="check"/></button></div><button @click="moreMenu=!moreMenu;userMenu=false"><Icon name="edit"/>系统设置</button><div class="d-menu-line"></div><button class="red" @click="logout"><Icon name="logout"/>退出登录</button></div>
 <div v-if="noticeMenu" class="d-notice-menu"><h3>最近消息 <small>最近记录中 {{unread}} 条未读</small></h3><button v-for="n in visibleNotifications.slice(0,5)" @click="readMessage(n)"><i class="dot" :class="{gray:n.is_read}"></i><span><b>{{n.title}}</b><small>{{displayMessage(n.content)}}</small></span></button><button class="d-link" @click="tab='notifications';noticeMenu=false">查看全部消息 <Icon name="arrow"/></button></div>
 <div v-if="moreMenu" class="d-more-menu"><div class="work-title"><h3>功能中心</h3><button aria-label="关闭功能中心" @click="moreMenu=false"><Icon name="close"/></button></div><button v-for="n in navigation" @click="tab=n.key;moreMenu=false;closeDetails()"><Icon :name="n.key==='statistics'?'chart':n.key==='audit'?'history':n.key==='users'?'user':'grid'"/>{{n.name}}<Icon class="push" name="arrow"/></button></div>
 </header>
 <main class="work-main" :inert="busy" :aria-busy="busy"><header class="d-page-heading"><div><h1>{{pageTitle}}</h1><p>{{selectedOrder?orderNumber(selectedOrder)+' · '+selectedOrder.node_code:tab==='overview'?(areas.find(a=>String(a.id)===areaFilter)?.name||'')+'运行态势与事件处置中心':subtitleMap[tab]||'统一管理巡检业务与配置'}}</p></div><div class="d-heading-actions"><small v-if="liveError" role="status" style="color:var(--red,#e67777)">实时更新中断：{{liveError}}</small><small>页面刷新 {{lastUpdate?lastUpdate.toLocaleTimeString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai'}):'尚未成功'}}</small><button :disabled="busy" @click="refresh"><Icon name="refresh"/>刷新</button><button v-if="tab==='audit'" class="primary" @click="exportCsv(visibleAudits,'审计日志')"><Icon name="download"/>导出日志</button></div></header>
 <div v-if="error" class="d-error" role="alert"><Icon name="warning"/>{{error}}<button aria-label="关闭错误" @click="error=''"><Icon name="close"/></button></div>
 <template v-if="selectedOrder">
 <button class="d-back" @click="backToOrders"><Icon name="arrow"/>返回工单列表</button><section class="d-order-summary work-panel"><div><small class="mono">{{orderNumber(selectedOrder)}}</small><h2>{{selectedOrder.title}}</h2><p>创建于 {{shortTime(selectedOrder.created_at)}} · 来源：{{selectedOrder.source||'巡检事件'}}</p></div><div class="d-inline"><span class="d-pill" :class="selectedOrder.priority==='HIGH'?'red':selectedOrder.priority==='LOW'?'teal':'amber'">{{severityName[selectedOrder.priority]}}风险</span><span class="d-pill" :class="selectedOrder.status==='COMPLETED'?'teal':'blue'">{{statusName[selectedOrder.status]}}</span></div></section>
 <div class="d-overview-grid"><section class="work-panel d-timeline-panel"><span class="eyebrow">处置进度</span><h2>工单时间线</h2><div class="d-timeline"><article v-for="e in selectedOrder.events" :key="e.id"><span class="d-timeline-dot"><Icon name="check"/></span><div><b>{{({CREATE:'创建',ASSIGN:'派单',ACCEPT:'接单',START:'到场'} as Row)[e.action]||actionLabels[e.action]||e.action}}</b><p>{{e.note||'操作已记录'}} · {{e.username}}</p></div><time>{{shortTime(e.created_at)}}</time></article><article v-if="!['COMPLETED','CANCELLED'].includes(selectedOrder.status)"><span class="d-timeline-dot waiting">{{(selectedOrder.events?.length||0)+1}}</span><div><b>{{({DRAFT:'派单',ASSIGNED:'接单',ACCEPTED:'开始处理',PROCESSING:'完成',REVIEW:'复核'} as Row)[selectedOrder.status]||statusName[selectedOrder.status]}}</b><p>{{selectedOrder.status==='PROCESSING'?'上传处置记录并等待复核':'等待后续处理'}}</p></div><time>—</time></article></div></section><section class="work-panel"><span class="eyebrow">工单信息</span><h2>处置详情</h2><dl class="d-detail-list"><div><dt>所属点位</dt><dd>{{selectedOrder.node_code}}</dd></div><div><dt>负责人</dt><dd>{{selectedOrder.assignee_name||'未分配'}}</dd></div><div><dt>要求完成时间</dt><dd>{{due(selectedOrder)}}</dd></div><div><dt>风险类型</dt><dd>{{severityName[selectedOrder.priority]}}风险巡检事件</dd></div><div><dt>处置要求</dt><dd>{{displayMessage(selectedOrder.description)||'按检查项目执行并提交现场记录'}}</dd></div></dl></section></div>
 <section class="work-panel d-order-workflow"><div class="work-title"><h2>处理与复核</h2><div class="d-inline"><button v-if="manager&&!['COMPLETED','CANCELLED'].includes(selectedOrder.status)" @click="open('schedule',{id:selectedOrder.id,priority:selectedOrder.priority,note:'调整优先级与期限'})">调整优先级/期限</button><button v-if="manager&&!['COMPLETED','CANCELLED','REVIEW'].includes(selectedOrder.status)" @click="assignOrder(selectedOrder)">派发/改派</button><template v-if="selectedOrder.assignee_id===identity.id||selectedOrder.participant_ids?.includes(identity.id)"><button v-if="selectedOrder.status==='ASSIGNED'" class="primary" @click="open('action',{id:selectedOrder.id,action:'accept',note:'接收任务'})">接单</button><button v-if="selectedOrder.status==='ACCEPTED'" class="primary" @click="open('action',{id:selectedOrder.id,action:'start',note:'开始处理'})">开始处理</button><button v-if="selectedOrder.status==='PROCESSING'" class="primary" @click="open('action',{id:selectedOrder.id,action:'submit',result:'',readings:'',note:'提交复核'})">提交处理结果</button></template><template v-if="manager&&selectedOrder.status==='REVIEW'"><button class="primary" @click="open('action',{id:selectedOrder.id,action:'approve',note:'复核通过'})">复核通过</button><button @click="open('action',{id:selectedOrder.id,action:'reject',note:''})">退回重做</button></template><button v-if="manager&&!['COMPLETED','CANCELLED'].includes(selectedOrder.status)" @click="open('action',{id:selectedOrder.id,action:'cancel',note:''})">取消工单</button></div></div><p class="work-pre">{{selectedOrder.result_text||'尚未提交处理反馈'}}</p><p class="work-pre">{{selectedOrder.readings}}</p><h3>现场照片</h3><input v-if="(selectedOrder.assignee_id===identity.id||selectedOrder.participant_ids?.includes(identity.id))&&['ACCEPTED','PROCESSING'].includes(selectedOrder.status)" type="file" :disabled="busy" accept="image/png,image/jpeg,image/webp" @change="upload"/><div v-for="a in selectedOrder.attachments" class="work-list-row"><span>{{a.original_name}}</span><button @click="act(()=>attachment(a.id))">查看图片</button></div></section>
 </template>
 <div v-else>
 <template v-if="tab==='overview'">
 <div class="d-metrics"><article class="d-metric"><span>在线节点</span><i class="metric-icon teal"><Icon name="nodes"/></i><div class="d-metric-value">{{onlineCount}}<small>/ {{zoneNodes.length}}</small></div><small>{{offlineCount?offlineCount+'个节点离线':'节点上报状态'}}</small><MetricSparkline variant="teal"/></article><article class="d-metric"><span>今日告警</span><i class="metric-icon red"><Icon name="warning"/></i><div class="d-metric-value">{{todayAlarms.length}}<small>条</small></div><small>{{todayAlarms.length?'需及时关注':'今日无新增'}}</small><MetricSparkline variant="red"/></article><article class="d-metric"><span>待派工单</span><i class="metric-icon amber"><Icon name="orders"/></i><div class="d-metric-value">{{orders.filter(o=>['DRAFT','ASSIGNED'].includes(o.status)).length}}<small>单</small></div><small>{{stats.overdue||0}} 单即将超时</small><MetricSparkline variant="amber"/></article><article class="d-metric"><span>平均响应</span><i class="metric-icon blue"><Icon name="clock"/></i><div class="d-metric-value">{{stats.averageResponseSeconds==null?'—':Math.round((stats.overviewAverageResponseSeconds??stats.averageResponseSeconds)/60)}}<small>分钟</small></div><small>当前授权范围统计</small><MetricSparkline variant="blue"/></article></div>
 <div class="d-overview-grid"><section class="work-panel d-tunnel-panel"><div class="work-title"><div><span class="eyebrow">空间态势</span><h2>管廊剖面示意</h2></div><button class="d-link" @click="tab='nodes'">查看节点管理 <Icon name="arrow"/></button></div><div class="tunnel"><div class="tunnel-labels"><span>北入口 · 0m</span><span>1号舱 · 320m</span><span>2号舱 · 680m</span><span>南出口 · 1.2km</span></div><div class="tunnel-arch"></div><div class="tunnel-road"></div><button v-for="(n,i) in zoneNodes" class="node-pin" :class="{alarm:nodeState(n)==='告警',offline:['离线','无数据'].includes(nodeState(n)),hovered:hoverNode===n.id}" :style="{left:(zoneNodes.length===3?20+i*30:10+i/Math.max(zoneNodes.length-1,1)*80)+'%',bottom:(i%2===0?90:68)+'px'}" @mouseenter="hoverNode=n.id" @mouseleave="hoverNode=null" @focus="hoverNode=n.id" @click="showNode(n)"><span class="pin-glyph"><i></i></span><small>{{n.code}}</small><div v-if="hoverNode===n.id" class="d-pin-tooltip"><div v-for="key in ['methane','temperature','humidity']"><small>{{metricName[key]}}</small><b>{{reading(n,key)}}</b><em>{{key==='methane'?'%LEL':key==='humidity'?'%RH':'°C'}}</em></div></div></button><div v-if="!zoneNodes.length" class="d-empty-tunnel">暂无节点</div></div><div class="node-legend"><button v-for="n in zoneNodes" :class="{highlight:hoverNode===n.id}" @mouseenter="hoverNode=n.id" @mouseleave="hoverNode=null" @click="showNode(n)"><b><i class="dot" :class="{red:nodeState(n)==='告警',amber:nodeState(n)==='离线',gray:['离线','无数据','时间未知','停用'].includes(nodeState(n))}"></i>{{n.code}}</b><small>{{reading(n,'methane')}} %LEL</small></button></div></section>
 <section class="work-panel d-alert-panel"><div class="work-title"><div><span class="eyebrow">实时事件</span><h2>实时告警流</h2></div><span class="d-pill red">{{zoneAlarms.filter(a=>!a.recovered_at).length}} 条进行中</span></div><div v-for="a in zoneAlarms.filter(a=>!a.recovered_at).slice(0,3)" class="d-alert-card" tabindex="0" :aria-label="'定位节点 '+a.code" @click="locateNode(a.node_id)" @keydown.enter.self="locateNode(a.node_id)" :class="{high:a.severity==='HIGH',linked:hoverNode===a.node_id}" @mouseenter="hoverNode=a.node_id" @mouseleave="hoverNode=null"><div><b>{{a.code}}</b><small>{{relativeTime(a.triggered_at)}}</small></div><p>{{displayMessage(a.reason)}}</p><div><small><i class="dot" :class="{red:a.severity==='HIGH'}"></i>{{(severityName[a.severity]||'中')+'风险'}}</small><button v-if="manager" @click.stop="open('order',{nodeId:a.node_id,alarmId:a.metric==='task'?undefined:a.id,title:a.code+' 风险处置',priority:a.severity,description:displayMessage(a.reason)})">派单</button></div></div><div v-if="!zoneAlarms.some(a=>!a.recovered_at)" class="d-empty-small"><Icon name="shield"/><p>当前区域暂无告警</p></div><button class="d-link d-centered" @click="tab='alarms'">查看全部告警 <Icon name="arrow"/></button></section></div>
 <section class="work-panel d-kanban-panel"><div class="work-title"><div><span class="eyebrow">运行处置</span><h2>工单看板</h2></div><button class="d-link" @click="tab='orders'">进入工单中心 <Icon name="arrow"/></button></div><div class="d-kanban"><section v-for="c in boardColumns"><header><i class="dot" :class="c.color"></i>{{c.name}}<small>{{boardOrders(c.status).length}}</small></header><article v-for="o in boardOrders(c.status).slice(0,3)" class="d-order-card" :class="{overdue:orderOverdue(o),urgent:c.status==='ASSIGNED'&&o.priority==='HIGH'}" @click="showOrder(o)" tabindex="0" @keydown.enter="showOrder(o)"><div class="d-card-top"><span class="d-pill" :class="o.priority==='HIGH'?'red':o.priority==='LOW'?'teal':'amber'">{{severityName[o.priority]}}风险</span><Icon name="more"/></div><h3>{{o.node_code}} <small class="mono">{{orderNumber(o)}}</small></h3><div class="d-order-note"><span>{{c.status==='DRAFT'?'等待指派处理人员':c.status==='REVIEW'?'现场处置已完成':'剩余处理时间'}}</span><b :class="{amber:c.status==='ASSIGNED'}">{{c.status==='DRAFT'?'立即派单':c.status==='ASSIGNED'?countdown(o):due(o)}}</b></div><footer><span><i class="d-avatar tiny">{{o.assignee_name?.slice(0,1)||'未'}}</i>{{o.assignee_name||'未分配'}}</span><div class="d-inline"><small v-if="c.status==='ASSIGNED'" class="d-board-countdown">{{countdown(o)}}</small><button v-if="manager&&c.status==='DRAFT'" class="d-pill amber" @click.stop="assignOrder(o)">待派发</button><span v-else class="d-pill" :class="c.color">{{statusName[o.status]}}</span></div></footer></article><div v-if="!boardOrders(c.status).length" class="d-board-empty">暂无{{c.name}}工单</div></section></div></section>
 </template>

 <template v-if="tab==='nodes'"><p class="data-quality-note">读数按采样时间判断时效；模拟不代表实测，离线和缺数不代表零。各指标来源与历史值见节点详情。真实环境未提供设备健康评分。</p><section class="work-panel d-table-panel"><div class="d-table-toolbar"><select v-model="sectionFilter" aria-label="筛选区段"><option value="">全部区段</option><option v-for="location in [...new Set(zoneNodes.map(n=>n.location))]">{{location}}</option></select><select v-model="nodeStatus" aria-label="筛选节点状态"><option v-for="status in ['全部状态','在线','告警','离线','无数据','停用','维护','时间未知']">{{status}}</option></select><div class="d-table-search"><Icon name="search"/><input v-model="search" placeholder="搜索节点编号或位置"/></div><span class="d-toolbar-fill"></span><small class="d-node-count"><i class="dot"></i>在线 {{visibleNodes.filter(n=>!['离线','无数据','停用'].includes(nodeState(n))).length}}<span>离线 {{visibleNodes.filter(n=>nodeState(n)==='离线').length}}</span></small><button aria-label="节点管理工具" title="节点管理工具" @click="nodeTools=!nodeTools"><Icon name="filter"/></button></div><div class="d-table-scroll"><table class="d-nodes-table" :class="{loading:busy||(isDemo&&route.query.state==='loading')}" :aria-busy="busy||(isDemo&&route.query.state==='loading')"><thead><tr><th><button class="d-sort" @click="sortDirection*=-1">节点编号 <span>↑</span></button></th><th>所属区段 <span>↑</span></th><th>甲烷 <span>↑</span></th><th>温度 <span>↑</span></th><th>湿度 <span>↑</span></th><th>在线状态</th><th>最近上报 <span>↑</span></th><th>操作</th></tr></thead><tbody v-if="busy||(isDemo&&route.query.state==='loading')"><tr v-for="row in 5"><td v-for="col in 8"><span class="d-cell-skeleton" :style="{width:([[76,105,100,65,70,107,97,60],[105,134,65,85,107,72,126,38],[134,85,86,107,72,93,78,52],[86,115,107,72,92,58,107,67],[115,144,72,93,58,79,135,43]][row-1]?.[col-1]||76)+'px'}"></span></td></tr></tbody><tbody v-else><tr v-for="n in pagedNodes" :key="n.id" :class="{located:locatedNode===n.id}"><td><div class="d-node-id"><span class="d-health" :class="{red:nodeState(n)==='告警'||(health(n)>0&&health(n)<70),gray:health(n)===0}" :style="{'--health':health(n)+'%'}" :title="isDemo?'演示规则分数，不是实测健康评分':'真实环境未提供设备健康评分'"><b>{{healthText(n)}}</b></span><div><b>{{n.code}}</b><small>{{isDemo?'演示分数':'健康评分未提供'}} {{healthText(n)}}</small></div></div></td><td>{{n.area_name}} · {{n.location}}</td><td v-for="metric in ['methane','temperature','humidity']"><div class="d-reading-cell"><span class="d-mini-track"><i :style="{width:Math.min(100,numeric(n,metric)/(metric==='methane'?50:metric==='temperature'?40:100)*100)+'%'}" :class="{red:metric==='methane'&&nodeState(n)==='告警'}"></i></span><b :class="{red:metric==='methane'&&nodeState(n)==='告警'}">{{reading(n,metric)}}</b><small>{{metric==='methane'?'%LEL':metric==='temperature'?'°C':'%RH'}}</small><small v-if="metric==='methane'" class="methane-origin">{{methaneOrigin(n,isDemo,clockNow)}}</small></div></td><td><i class="dot" :class="{gray:['离线','无数据','停用'].includes(nodeState(n))}"></i>{{['正常','告警'].includes(nodeState(n))?'在线':nodeState(n)}}</td><td>{{n.last_seen?reportAge(n.last_seen):'—'}}</td><td><button class="d-link" @click="showNode(n)">查看 <Icon name="arrow"/></button></td></tr></tbody></table></div><div v-if="!visibleNodes.length" class="d-empty-state"><Icon name="search"/><h3>未找到匹配的节点</h3><p>请尝试调整筛选条件或搜索关键词</p><button @click="search='';nodeStatus='全部状态'">清除筛选</button></div><div class="d-pagination node-pagination"><small>共 {{visibleNodes.length}} 条</small><button :disabled="nodePage<=1" aria-label="上一页" @click="nodePage--">‹</button><button v-for="p in Math.max(1,Math.ceil(visibleNodes.length/pageSize))" :class="{current:nodePage===p}" @click="nodePage=p">{{p}}</button><button :disabled="nodePage*pageSize>=visibleNodes.length" aria-label="下一页" @click="nodePage++">›</button><select v-model="pageSize" aria-label="每页数量"><option :value="20">20 条/页</option><option :value="50">50 条/页</option></select></div></section><div v-if="manager&&nodeTools" class="d-management-tools"><button @click="open('node',{areaId:Number(areaFilter)||areas[0]?.id,platform:'SIMULATOR'})">新增节点</button><button @click="manageAreas">管廊与区域</button><button @click="showRules">告警规则</button><button @click="tab='simulator'">数据联调控制台</button></div></template>

 <template v-if="tab==='areas'"><section class="work-panel"><div class="work-title"><h2>管廊管理</h2><button v-if="isAdmin" @click="open('corridor')">新增管廊</button></div><div v-for="c in corridors" class="work-list-row"><b>{{c.name}}</b><span>{{c.description}}</span><template v-if="isAdmin"><button @click="open('corridor',{...c})">编辑</button><button @click="remove('/corridors/'+c.id,c.name)">删除</button></template></div></section><section class="work-panel"><div class="work-title"><h2>区域管理</h2><button v-if="isAdmin" @click="open('area',{corridorId:corridors[0]?.id})">新增区域</button></div><div v-for="a in areas" class="work-list-row"><b>{{a.name}}</b><span>{{a.description}}</span><template v-if="isAdmin"><button @click="open('area',{...a,corridorId:a.corridor_id})">编辑</button><button @click="remove('/areas/'+a.id,a.name)">删除</button></template></div></section><section class="work-panel"><div class="work-title"><h2>区段管理</h2><select v-model="areaFilter" @change="loadSections"><option v-for="a in areas" :value="String(a.id)">{{a.name}}</option></select><button @click="open('section',{areaId:areaFilter||areas[0]?.id})">新增区段</button></div><div v-for="s in sections" class="work-list-row"><b>{{s.name}}</b><button @click="open('section',{...s,areaId:s.area_id})">编辑</button><button @click="remove('/sections/'+s.id,s.name)">删除</button></div><p v-if="!sections.length" class="work-empty">暂无区段，可新增后在节点编辑中关联。</p></section></template>
 <template v-if="tab==='simulator'"><div class="work-toolbar"><label><input v-model="simulationRunning" type="checkbox"/>周期更新正常读数</label></div><div class="work-grid"><section v-for="n in nodes" class="work-panel"><h2>{{n.code}} · {{n.location}}</h2><p>{{nodeDisplayState(n)}} · {{latest(n,'methane')}}</p><div class="work-actions"><button v-for="s in [{key:'normal',name:'正常/恢复'},{key:'gas',name:'气体异常'},{key:'heat',name:'温度异常'},{key:'offline',name:'停止上报'}]" :disabled="busy||!manager" @click="simulate(n,s.key)">{{s.name}}</button><button @click="editNode(n)">编辑节点</button><button @click="remove('/nodes/'+n.id,n.code)">删除</button></div></section></div></template>
 <template v-if="tab==='rules'"><div class="work-toolbar"><button @click="open('rule',{areaId:areaFilter||areas[0]?.id,metric:'methane',threshold:35,durationSeconds:0,severity:'HIGH',enabled:true})">配置规则</button><span>现场使用前，须按适用标准核定告警阈值。</span></div><section class="work-panel"><table><thead><tr><th>指标</th><th>阈值</th><th>持续秒数</th><th>等级</th><th>启用</th><th>操作</th></tr></thead><tbody><tr v-for="r in rules"><td>{{metricName[r.metric]}}</td><td>{{r.threshold_value}}</td><td>{{r.duration_seconds}}</td><td>{{severityName[r.severity]}}</td><td>{{r.enabled?'是':'否'}}</td><td><button @click="open('rule',{...r,areaId:r.area_id,threshold:r.threshold_value,durationSeconds:r.duration_seconds})">编辑</button></td></tr></tbody></table><p v-if="!rules.length" class="work-empty">暂无规则，请先配置告警规则。</p></section></template>
 <template v-if="tab==='alarms'"><div class="work-toolbar"><button @click="exportCsv(alarms,'告警记录')">导出</button></div><section class="work-panel work-scroll"><table><thead><tr><th>节点</th><th>级别</th><th>原因</th><th>触发时间</th><th>恢复</th><th>确认</th><th>操作</th></tr></thead><tbody><tr v-for="a in alarms"><td>{{a.code}}</td><td>{{severityName[a.severity]}}</td><td>{{displayMessage(a.reason)}}</td><td>{{format(a.triggered_at)}}</td><td>{{format(a.recovered_at)}}</td><td>{{statusName[a.status]}}</td><td><div class="work-actions"><button v-if="manager&&a.status==='OPEN'" @click="open('ack',{id:a.id,note:''})">确认</button><button @click="open('order',{nodeId:a.node_id,alarmId:a.id,title:a.code+' '+metricName[a.metric]+'告警处置',priority:a.severity,description:displayMessage(a.reason)})">建工单</button></div></td></tr></tbody></table><p v-if="!alarms.length" class="work-empty">暂无告警</p></section></template>
 <template v-if="tab==='orders'"><section class="work-panel d-table-panel"><div class="d-table-toolbar"><div class="d-order-tabs"><button v-for="c in [{status:'ALL',name:'全部工单'},...boardColumns]" :class="{selected:orderFilter===c.status}" @click="orderFilter=c.status">{{c.name}} <small>{{c.status==='ALL'?orders.length:boardOrders(c.status).length}}</small></button></div><span class="d-toolbar-fill"></span><button v-if="manager" class="primary" @click="open('order',{nodeId:nodes[0]?.id,priority:'MEDIUM'})">+ 新建工单</button></div><div class="d-table-scroll"><table class="d-orders-table"><thead><tr><th><input type="checkbox" :checked="selectedIds.length>0&&selectedIds.length===pagedOrders.filter(o=>!['COMPLETED','CANCELLED','REVIEW'].includes(o.status)).length" aria-label="选择全部工单" @change="selectAllOrders(($event.target as HTMLInputElement).checked)"/></th><th>编号</th><th>点位 <span>↑</span></th><th>风险 <span>↑</span></th><th>状态 <span>↑</span></th><th>负责人</th><th>截止时间 <span>↑</span></th><th>操作</th></tr></thead><tbody><tr v-for="o in pagedOrders"><td><input v-model="selectedIds" type="checkbox" :value="o.id" :disabled="['COMPLETED','CANCELLED','REVIEW'].includes(o.status)" :aria-label="'选择 '+orderNumber(o)"/></td><td class="mono"><button class="d-link" @click="showOrder(o)">{{orderNumber(o)}}</button></td><td><button class="d-link teal" @click="showNode(nodes.find(n=>n.id===o.node_id)!)">{{o.node_code}}</button></td><td><span class="d-pill" :class="o.priority==='HIGH'?'red':o.priority==='LOW'?'teal':'amber'"><i></i>{{severityName[o.priority]}}风险</span></td><td><span class="d-pill" :class="['COMPLETED','REVIEW'].includes(o.status)?'teal':o.status==='PROCESSING'?'blue':'amber'"><i></i>{{statusName[o.status]}}</span></td><td><span class="d-inline"><i class="d-avatar tiny">{{o.assignee_name?.slice(0,1)||'未'}}</i>{{o.assignee_name||'未分配'}}<Icon v-if="!o.assignee_name" name="chevron"/></span></td><td :class="{red:o.due_at&&new Date(o.due_at).getTime()-Date.now()<3600000}">{{due(o)}}</td><td><button v-if="manager&&o.status==='DRAFT'" class="d-dispatch" @click="assignOrder(o)">派单</button><button v-else class="d-link" @click="showOrder(o)">详情 <Icon name="arrow"/></button></td></tr></tbody></table></div><div v-if="!visibleOrders.length" class="d-empty-state"><Icon name="orders"/><h3>暂无匹配工单</h3><p>调整筛选条件或创建新的巡检工单</p></div><div class="d-pagination"><small>共 {{visibleOrders.length}} 条</small><button :disabled="orderPage<=1" aria-label="上一页" @click="orderPage--">‹</button><button v-for="p in Math.max(1,Math.ceil(visibleOrders.length/pageSize))" :class="{current:orderPage===p}" @click="orderPage=p">{{p}}</button><button :disabled="orderPage*pageSize>=visibleOrders.length" aria-label="下一页" @click="orderPage++">›</button><select v-model="pageSize" aria-label="每页数量"><option :value="20">20 条/页</option><option :value="50">50 条/页</option></select></div></section><div v-if="selectedIds.length&&manager" class="d-batch-bar"><span><b>{{selectedIds.length}}</b> 项已选择</span><button @click="assignBatchOrders()"><Icon name="user"/>批量指派</button><button @click="exportCsv(orders.filter(o=>selectedIds.includes(o.id)),'已选工单')">导出状态</button><button class="red" @click="selectedIds=[]">清除</button><button aria-label="取消选择" @click="selectedIds=[]"><Icon name="close"/></button></div></template>

 <SettingsPanel v-if="tab==='settings'" :profile="profile" :areas="areas" :readonly="viewRole==='readonly'" :active-tab="settingTab" @tab="settingTab=$event" @updated="profile=$event" @notify="success=$event"/>
 <template v-if="tab==='patrol'"><section v-if="manager" class="work-panel"><div class="work-title"><h2>巡检计划</h2><button @click="open('plan',{areaId:areas[0]?.id,periodHours:24,nodeIds:[],checkItems:'检查设备外观、现场读数并记录异常'})">新建计划</button></div><div v-for="p in plans" class="work-list-row"><b>{{p.name}}</b><span>{{p.area_name}} · {{p.assignee_name}} · 每{{p.period_hours}}小时</span><span>{{p.enabled?'启用':'停用'}}</span><button :disabled="busy||!p.enabled" @click="generate(p)">立即生成</button><button :disabled="busy" @click="togglePlan(p)">{{p.enabled?'停用':'启用'}}</button></div><p v-if="!plans.length" class="work-empty">暂无巡检计划</p></section><section class="work-panel"><h2>巡检执行任务</h2><div v-for="r in runs" class="work-list-row"><b>#{{r.id}} {{r.name}}</b><span>{{r.assignee_name}}</span><span>{{statusName[r.status]}}</span><span>{{format(r.created_at)}}</span><button @click="showRun(r)">执行记录</button></div><p v-if="!runs.length" class="work-empty">暂无巡检任务</p></section></template>
 <template v-if="tab==='handbooks'"><div class="work-toolbar"><input v-model="search" placeholder="搜索手册"/><button v-if="manager" @click="open('handbook')">新增手册</button></div><section v-for="b in books.filter(b=>(b.title+b.category).includes(search))" class="work-panel"><div class="work-title"><h2>{{b.title}}</h2><div class="work-actions"><button v-if="manager" @click="open('handbook',{...b,reviewPoints:b.review_points,source:b.reference_source})">编辑</button><button v-if="manager" @click="remove('/handbooks/'+b.id,b.title)">删除</button></div></div><small>{{b.category}} · {{format(b.updated_at)}}</small><h3>处置步骤</h3><p class="work-pre">{{b.steps}}</p><h3>复核要点</h3><p class="work-pre">{{b.review_points||'未填写'}}</p><small class="work-muted">参考来源：{{b.reference_source||'未填写'}} · 人工维护手册，未接入 Agent</small></section><p v-if="!books.length" class="work-empty">暂无处置手册，可先由值班长维护标准流程。</p></template>
 <template v-if="tab==='notifications'"><section class="work-panel"><div v-for="n in visibleNotifications" class="work-list-row"><b>{{n.title}}</b><span>{{displayMessage(n.content)}}</span><small>{{format(n.created_at)}}</small><button :disabled="n.is_read||busy" @click="readMessage(n)">{{n.is_read?'已读':'标为已读'}}</button></div><p v-if="!visibleNotifications.length" class="work-empty">暂无消息</p></section></template>
 <template v-if="tab==='users'&&isAdmin"><div class="work-toolbar"><button @click="open('user',{role:'INSPECTOR'})">新建用户</button></div><section class="work-panel"><table><thead><tr><th>账号</th><th>姓名</th><th>角色</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="u in users"><td>{{u.username}}</td><td>{{u.display_name||'—'}}</td><td>{{roleName[u.role_code]}}</td><td>{{u.enabled?'启用':'禁用'}}</td><td><button @click="open('editUser',{...u,displayName:u.display_name,role:u.role_code,areas:u.areas||[]})">权限与区域</button> <button @click="open('password',{id:u.id})">重置密码</button></td></tr></tbody></table></section></template>
 <template v-if="tab==='audit'&&['ADMIN','MANAGER'].includes(identity.role)"><section class="work-panel d-table-panel"><div class="d-table-toolbar"><select v-model="auditActor" aria-label="筛选操作人"><option value="">全部操作人</option><option v-for="name in [...new Set(audits.map(a=>a.actor_name))]">{{name}}</option></select><select v-model="auditAction" aria-label="筛选动作"><option value="">全部动作</option><option v-for="action in [...new Set(audits.map(a=>a.action))]" :value="action">{{actionLabels[action]||action}}</option></select><details class="d-date-range"><summary><Icon name="clock"/><span>{{auditFrom||auditTo?(auditFrom||'不限')+' — '+(auditTo||'不限'):'选择日期范围'}}</span></summary><div class="d-date-popover"><label>开始日期<input v-model="auditFrom" type="date" aria-label="审计开始日期"/></label><label>结束日期<input v-model="auditTo" type="date" aria-label="审计结束日期"/></label><button type="button" @click="auditFrom='';auditTo=''">清除日期</button></div></details><span class="d-toolbar-fill"></span><span class="d-record-count">共 {{visibleAudits.length}} 条记录</span></div><div class="d-table-scroll"><table class="d-audit-table"><thead><tr><th>时间</th><th>操作人</th><th>对象</th><th>动作</th><th>变更前</th><th>变更后</th><th></th></tr></thead><tbody><tr v-for="a in visibleAudits" @click="selectedAudit=a" tabindex="0" @keydown.enter="selectedAudit=a"><td class="mono">{{auditTimestamp(a.created_at)}}</td><td><span class="d-inline"><i class="d-avatar tiny" :class="{system:a.actor_name==='系统'}">{{a.actor_name.slice(0,1)}}</i>{{a.actor_name}}</span></td><td class="teal mono">{{auditObjectLabel(a)}}</td><td>{{actionLabels[a.action]||a.action}}</td><td><code>{{(a.before_value||'—').slice(0,35)}}</code></td><td><code class="d-after">{{(a.after_value||'—').slice(0,35)}}</code></td><td><Icon name="arrow"/></td></tr></tbody></table></div><div v-if="!visibleAudits.length" class="d-empty-state"><Icon name="history"/><h3>暂无匹配记录</h3></div></section></template>

 <template v-if="tab==='statistics'&&['ADMIN','MANAGER'].includes(identity.role)"><div class="d-report-metrics"><article><small>巡检点位完成率</small><Icon name="chart"/><b class="teal">{{stats.coverage?.total?(stats.coverage.checked/stats.coverage.total*100).toFixed(1):'—'}}<em>%</em></b><span>所选期间的点次完成情况</span></article><article><small>平均接单响应</small><Icon name="chart"/><b class="blue">{{stats.averageResponseSeconds==null?'—':(stats.averageResponseSeconds/60).toFixed(1)}}<em>分钟</em></b><span>从工单创建至接单</span></article><article><small>告警恢复率</small><Icon name="chart"/><b class="amber">{{stats.alarmRecovery?.total?(stats.alarmRecovery.recovered/stats.alarmRecovery.total*100).toFixed(1):'—'}}<em>%</em></b><span>已恢复告警占比</span></article><article><small>本月告警</small><Icon name="chart"/><b class="red">{{stats.monthlyAlarms??stats.alarms?.reduce((s:number,a:Row)=>s+Number(a.total),0)??0}}<em>条</em></b><span>当前授权范围统计</span></article></div><div class="d-overview-grid"><section class="work-panel d-report-panel"><div class="work-title"><div><span class="eyebrow">处置效率</span><h2>近12周巡检完成趋势</h2></div><div class="d-report-legend"><small><i></i>计划覆盖率</small><small><i></i>实际完成率</small></div></div><ReportChart :values="stats.weekly"/></section><section class="work-panel d-report-ranking"><span class="eyebrow">风险排行</span><h2>高频风险点位</h2><article v-for="(n,i) in stats.repeatNodes?.slice(0,4)"><small>{{String(Number(i)+1).padStart(2,'0')}}</small><i class="dot" :class="i===0?'red':i===3?'':'amber'"></i><div><b>{{n.code}}</b><small>累计重复告警</small></div><span>{{n.total}} 次</span></article><div v-if="!stats.repeatNodes?.length" class="d-empty-small"><Icon name="shield"/><p>暂无重复告警点位</p></div></section></div><section class="work-panel d-report-tools"><div class="work-title"><h2>报表筛选与导出</h2><small>默认最近30天</small></div><div class="work-toolbar"><select v-model="reportArea"><option value="">全部授权区域</option><option v-for="a in areas" :value="a.id">{{a.name}}</option></select><label>开始<input type="datetime-local" v-model="reportFrom"/></label><label>结束<input type="datetime-local" v-model="reportTo"/></label><button @click="refreshStats">查询统计</button><button @click="exportReport('orders')"><Icon name="download"/>导出工单报表</button><button @click="exportReport('alarms')"><Icon name="download"/>导出告警报表</button></div><small>逾期工单：{{stats.overdue||0}} 单。可选择一天的时间范围导出日报。</small></section></template>

 </div></main>
 <div v-if="selectedNode" class="d-drawer-overlay" @click.self="selectedNode=null"><aside class="d-drawer d-node-drawer"><header><div><span class="eyebrow">节点详情</span><h2>{{selectedNode.code}}</h2></div><button aria-label="关闭节点详情" @click="selectedNode=null"><Icon name="close"/></button></header><div class="d-drawer-body"><div class="d-node-profile"><span class="d-health large" :class="{red:nodeState(selectedNode)==='告警'||(health(selectedNode)>0&&health(selectedNode)<70),gray:health(selectedNode)===0}" :style="{'--health':health(selectedNode)+'%'}"><b>{{healthText(selectedNode)}}</b></span><div><b>{{selectedNode.area_name}} · {{selectedNode.location}}</b><span v-if="nodeState(selectedNode)==='告警'" class="d-pill red"><i></i>需处理</span><span v-else class="d-pill" :class="['离线','无数据','时间未知','停用'].includes(nodeState(selectedNode))?'amber':'teal'">{{nodeState(selectedNode)==='离线'?'通信离线':nodeDisplayState(selectedNode)}}</span></div><small class="push"><i class="dot" :class="{gray:['离线','无数据','时间未知','停用'].includes(nodeState(selectedNode))}"></i>{{['离线','无数据','时间未知','停用'].includes(nodeState(selectedNode))?'连接状态待核对':'有近期上报'}}</small></div><div class="d-node-metrics"><div v-for="key in ['methane','temperature','humidity']"><small>{{metricName[key]}}</small><b :class="{red:key==='methane'&&nodeState(selectedNode)==='告警'}">{{reading(selectedNode,key)}}</b><em>{{key==='methane'?'%LEL':key==='humidity'?'%RH':'°C'}}</em></div></div><TelemetryStatusPanel :node="selectedNode" :now-ms="clockNow"/><div class="d-chart-heading"><div><span class="eyebrow muted">24小时趋势</span><h3>指标曲线</h3></div><div class="d-chart-legend"><button v-for="key in ['methane','temperature','humidity']" :class="key==='methane'?'teal':key==='temperature'?'amber':'blue'" @click="historyMetric=key;loadHistory()"><i></i>{{metricName[key]}}</button><button @click="historyMetric='all';loadHistory()">全部</button></div></div><div class="d-node-chart"><svg viewBox="0 0 450 200" preserveAspectRatio="none" aria-label="24小时监测曲线"><g class="d-chart-grid"><path d="M34 10H436M34 51H436M34 92H436M34 133H436M34 174H436M34 10V174M135 10V174M235 10V174M336 10V174M436 10V174"/></g><g class="d-chart-axis"><text v-for="(v,i) in [100,75,50,25,0]" x="22" :y="29+i*41" text-anchor="end">{{v}}</text><text v-for="(v,i) in ['00:00','06:00','12:00','18:00','现在']" :x="34+i*100.5" y="190" text-anchor="middle">{{v}}</text></g><polyline v-for="key in ['methane','humidity','temperature']" :key="key+points(key)" class="d-live-wave" pathLength="1" :points="points(key)" fill="none" :stroke="key==='methane'?'#29d9cd':key==='temperature'?'#f5b519':'#6e9ffb'" stroke-width="2"/></svg><span v-if="!history.length" class="d-chart-no-data">暂无历史数据</span></div><div class="d-chart-heading"><div><span class="eyebrow muted">告警配置</span><h3>预警阈值</h3></div><button v-if="manager" class="d-link teal" @click="editNode(selectedNode)"><Icon name="edit"/>设备配置</button></div><div class="d-node-rules"><label v-for="key in ['methane','temperature','humidity']"><span>{{key==='methane'?'甲烷浓度':key==='temperature'?'环境温度':'环境湿度'}} <small>{{key==='methane'?'%LEL':key==='temperature'?'°C':'%RH'}}</small></span><input v-model.number="nodeThresholds[key]" :disabled="!manager" type="number" step="any" :aria-label="metricName[key]+'预警阈值'" :placeholder="manager?'未配置':'—'"/></label></div><div class="d-chart-heading"><div><span class="eyebrow muted">事件记录</span><h3>最近告警</h3></div></div><div v-for="a in alarms.filter(a=>a.node_id===selectedNode!.id).slice(0,3)" class="d-node-alarm"><i class="dot" :class="{red:a.severity==='HIGH'}"></i><span>{{displayMessage(a.reason)}}<small>{{format(a.triggered_at)}}</small></span></div><p v-if="!alarms.some(a=>a.node_id===selectedNode!.id)" class="d-node-no-alarm">暂无告警记录</p></div><footer><button @click="selectedNode=null">取消</button><button v-if="manager" class="primary" :disabled="busy" @click="saveThresholds"><Icon name="edit"/>保存阈值</button></footer></aside></div>
 <div v-if="selectedAudit" class="d-drawer-overlay" @click.self="selectedAudit=null"><aside class="d-drawer d-audit-drawer"><header><div><span class="eyebrow">审计详情</span><h2>{{actionLabels[selectedAudit.action]||selectedAudit.action}}</h2></div><button aria-label="关闭审计详情" @click="selectedAudit=null"><Icon name="close"/></button></header><div class="d-drawer-body"><dl class="d-audit-meta"><div><dt>操作时间</dt><dd>{{auditTimestamp(selectedAudit.created_at)}}</dd></div><div><dt>操作人</dt><dd>{{selectedAudit.actor_name}}</dd></div><div><dt>目标对象</dt><dd>{{auditObjectLabel(selectedAudit)}}</dd></div><div><dt>操作编号</dt><dd>#{{selectedAudit.id}}</dd></div></dl><div class="d-chart-heading"><div><span class="eyebrow muted">字段变更</span><h3>Before → After</h3></div></div><div class="d-diff"><header>配置快照 <small>1 项变更</small></header><pre>{
  "objectId": "{{selectedAudit.object_id}}",
<span class="removed">- "value": "{{selectedAudit.before_value||'—'}}",</span>
<span class="added">+ "value": "{{selectedAudit.after_value||'—'}}",</span>
  "updatedBy": "{{selectedAudit.actor_name}}"
}</pre></div><div class="d-audit-sealed"><Icon name="check"/><div><b>操作与变更已记录</b><small>记录操作人与变更内容，可追溯</small></div></div></div></aside></div>
 <div v-if="form&&formType==='assign'" class="d-drawer-overlay d-assign-overlay" @click.self="!busy&&(form=null)"><form class="d-drawer d-assign-drawer" @submit.prevent="save"><header><div><span class="eyebrow">派单</span><h2>{{form.orderIds?.length?'批量指派 '+form.orderIds.length+' 个工单':form.number}}</h2><small>{{form.node_code}} <span class="red">{{severityName[form.priority]}}风险</span></small></div><button type="button" aria-label="关闭派单" :disabled="busy" @click="form=null"><Icon name="close"/></button></header><div class="d-drawer-body"><section class="d-selected-people"><div class="work-title"><div><h3>已选人员</h3><small>请选择两名工人协同处理</small></div><b>{{form.participantIds.length}}/2</b></div><div class="d-person-chips"><button v-for="id in form.participantIds" type="button" @click="togglePerson(id)"><i class="d-avatar tiny">{{users.find(u=>u.id===id)?.display_name?.slice(0,1)||users.find(u=>u.id===id)?.username.slice(0,1)}}</i>{{users.find(u=>u.id===id)?.display_name||users.find(u=>u.id===id)?.username}}<Icon name="close"/></button><small v-if="!form.participantIds.length">暂未选择人员</small></div></section><section class="d-recommended"><div class="work-title"><div><h3>可选巡检员</h3><small>仅显示对全部所选区域有授权的启用巡检员，按姓名排序</small></div></div><label class="d-note-label">搜索巡检员<input v-model="assigneeSearch" placeholder="搜索姓名或账号" aria-label="搜索巡检员" maxlength="100"/></label><button v-for="u in dispatchCandidates" :key="u.id" type="button" class="d-person-card" :class="{chosen:form.participantIds.includes(u.id)}" :disabled="!u.enabled" @click="togglePerson(u.id)"><i class="d-avatar">{{(u.display_name||u.username).slice(0,1)}}<em :class="{busy:orders.filter(o=>o.assignee_id===u.id&&!['COMPLETED','CANCELLED'].includes(o.status)).length>1}"></em></i><span><b>{{u.display_name||u.username}}</b><small>W-{{String(u.id).padStart(3,'0')}} <i>|</i> {{areas.filter(a=>u.areas?.some((id:number)=>Number(id)===a.id)).map(a=>a.name).join('、')||'未分区'}}</small><span class="d-worker-tags"><em>现场巡检</em><em>应急处理</em></span></span><span class="d-person-tasks"><b>{{orders.filter(o=>o.assignee_id===u.id&&!['COMPLETED','CANCELLED'].includes(o.status)).length}} 个进行中</b><small>{{u.enabled?'当前可指派':'当前不可指派'}}</small></span><i class="d-person-check"><Icon v-if="form.participantIds.includes(u.id)" name="check"/></i></button><p v-if="!dispatchCandidates.length" class="work-empty">{{dispatchEmptyMessage}}</p></section><section class="d-dispatch-options"><label><span>优先级</span><div><button type="button" :class="{selected:form.priority!=='HIGH'}" @click="form.priority='MEDIUM'">普通</button><button type="button" :class="{selected:form.priority==='HIGH'}" @click="form.priority='HIGH'">紧急</button></div></label><label><span>截止时间</span><div><button v-for="d in [{v:'30',name:'30分钟'},{v:'120',name:'2小时'},{v:'480',name:'今日'}]" type="button" :class="{selected:form.quickDue===d.v}" @click="form.quickDue=d.v;form.dueAt=d.v==='480'?new Date(new Date().setHours(23,59,0,0)).toISOString():new Date(Date.now()+Number(d.v)*60000).toISOString()">{{d.name}}</button></div></label><label class="d-note-label">派单备注<textarea v-model="form.note" placeholder="填写处理要求与注意事项" maxlength="2000"></textarea></label></section></div><footer><span v-if="error" class="red">{{error}}</span><button type="button" :disabled="busy" @click="form=null">取消</button><button class="primary" :disabled="busy||!dispatchCrewValid">确认派单（{{form.participantIds.length}}人）</button></footer></form></div>
 <div v-if="success" class="d-success-toast" role="status"><span><Icon name="check"/></span><div><b>操作成功</b><small>{{success}}</small></div></div>

 <div v-if="selectedRun" class="work-overlay" @click.self="selectedRun=null"><section class="work-dialog wide" :inert="busy"><div class="work-title"><h2>{{selectedRun.name}} #{{selectedRun.id}}</h2><button @click="selectedRun=null">关闭</button></div><article v-for="p in selectedRun.points" class="work-panel"><h3>{{p.code}} · {{p.location}}</h3><p class="work-pre">{{p.check_items}}</p><p>{{p.checked_at?format(p.checked_at):'待检查'}}</p><p>{{p.result_text}}</p><label v-if="!p.checked_at&&selectedRun.assignee_id===identity.id">现场照片<input type="file" :disabled="busy" accept="image/png,image/jpeg" @change="uploadPatrol($event,p)"/></label><div v-for="a in p.attachments" class="work-list-row"><span>{{a.original_name}}</span><button @click="act(()=>attachment(a.id,true))">查看照片</button></div><span v-if="p.abnormal" class="work-tag red">异常 · 工单 #{{p.order_id}}</span><button v-if="!p.checked_at&&selectedRun.assignee_id===identity.id" @click="open('patrolResult',{id:p.id,result:'',abnormal:false})">填写检查结果</button></article></section></div>
 <div v-if="form&&formType!=='assign'" class="work-overlay form-layer" @click.self="!busy&&(form=null)"><form class="work-dialog" @submit.prevent="save"><div class="work-title"><h2>{{({user:'新增用户',editUser:'用户权限与区域',password:'重置密码',corridor:'管廊信息',area:'区域信息',section:'新增区段',node:'新增节点',editNode:'编辑节点',rule:'告警规则',order:'新建工单',schedule:'调整优先级与期限',assign:'派发工单',ack:'确认告警',action:'工单操作',handbook:'处置手册',plan:'巡检计划',patrolResult:'点位检查结果'} as Row)[formType]}}</h2><button type="button" :disabled="busy" @click="form=null">关闭</button></div>
 <template v-if="['user','editUser'].includes(formType)"><label v-if="formType==='user'">账号<input v-model="form.username" required maxlength="64" autocomplete="off"/></label><label>姓名<input v-model="form.displayName" maxlength="100"/></label><label>角色<select v-model="form.role"><option v-for="(name,key) in roleName" :value="key">{{name}}</option></select></label><template v-if="formType==='editUser'"><label class="work-check"><input v-model="form.enabled" type="checkbox"/>启用账号</label><label>授权区域（可多选）<select v-model="form.areas" multiple><option v-for="a in areas" :value="a.id">{{a.name}}</option></select></label><small>管理员可访问全部区域，其他角色只能访问已授权区域。</small></template></template>
 <label v-if="['user','password'].includes(formType)">密码<input v-model="form.password" type="password" minlength="12" maxlength="72" required autocomplete="new-password"/><small>至少12位，最多72个ASCII字符。</small></label>
 <template v-if="['corridor','area','section','plan'].includes(formType)"><label>名称<input v-model="form.name" required maxlength="100"/></label></template>
 <label v-if="formType==='area'">所属管廊<select v-model="form.corridorId" required><option v-for="c in corridors" :value="c.id">{{c.name}}</option></select></label><label v-if="['area','corridor'].includes(formType)">说明<textarea v-model="form.description" maxlength="500"/></label>
 <label v-if="['section','node','rule','plan'].includes(formType)">所属区域<select v-model="form.areaId" required><option v-for="a in areas" :value="a.id">{{a.name}}</option></select></label>
 <template v-if="['node','editNode'].includes(formType)"><label v-if="formType==='node'">节点编号<input v-model="form.code" required maxlength="64"/></label><label>位置<input v-model="form.location" required maxlength="200"/></label><label>外部设备编号（预留）<input v-model="form.externalId" maxlength="128"/></label><label>数据平台<select v-model="form.platform"><option value="SIMULATOR">本地联调</option><option>HUAWEI_IOT</option><option>MQTT</option></select></label><small>选择平台仅保存绑定信息，真实平台连接尚未启用。</small><template v-if="formType==='editNode'"><label>负责人<select v-model="form.ownerId"><option :value="null">未分配</option><option v-for="u in users.filter(u=>u.enabled)" :value="u.id">{{u.display_name||u.username}}</option></select></label><label>监测指标（可多选）<select v-model="form.metricList" multiple required><option v-for="k in ['methane','temperature','humidity','infrared']" :value="k">{{metricName[k]}}</option></select></label><label>所属区段<select v-model="form.sectionId"><option :value="null">未分配</option><option v-for="s in sections" :value="s.id">{{s.name}}</option></select></label><div class="work-form-grid"><label>上报周期（秒）<input v-model.number="form.reportSeconds" type="number" min="5" max="86400" required/></label><label>X位置（0～100）<input v-model.number="form.x" type="number" min="0" max="100"/></label><label>Y位置（0～100）<input v-model.number="form.y" type="number" min="0" max="100"/></label></div><label class="work-check"><input v-model="form.enabled" type="checkbox"/>启用节点</label><label class="work-check"><input v-model="form.maintenance" type="checkbox"/>维护中</label></template></template>
 <template v-if="formType==='rule'"><label>监测指标<select v-model="form.metric"><option v-for="key in ['methane','temperature','humidity','infrared']" :value="key">{{metricName[key]}}</option></select></label><label>超过此阈值告警<input v-model.number="form.threshold" type="number" step="any" required/></label><label>持续时间（秒）<input v-model.number="form.durationSeconds" type="number" min="0" max="86400" required/></label><label>告警级别<select v-model="form.severity"><option v-for="(name,key) in severityName" :value="key">{{name}}</option></select></label><label class="work-check"><input v-model="form.enabled" type="checkbox"/>启用规则</label></template>
 <template v-if="formType==='order'"><label>关联节点<select v-model="form.nodeId" required><option v-for="n in nodes" :value="n.id">{{n.code}} · {{n.location}}</option></select></label><label>标题<input v-model="form.title" required maxlength="200"/></label><label>描述<textarea v-model="form.description" maxlength="2000"/></label></template>
 <label v-if="['order','assign','schedule'].includes(formType)">优先级<select v-model="form.priority"><option v-for="(name,key) in severityName" :value="key">{{name}}</option></select></label>
 <template v-if="['assign','plan'].includes(formType)"><label>执行人<select v-model="form.assigneeId" required><option v-for="u in users.filter(u=>u.role_code==='INSPECTOR'&&u.enabled)" :value="u.id">{{u.display_name||u.username}}</option></select></label></template>
 <label v-if="['assign','schedule'].includes(formType)">截止时间<input v-model="form.dueAt" type="datetime-local"/></label>
 <label v-if="['assign','schedule','ack','action'].includes(formType)">备注<textarea v-model="form.note" :required="['assign','schedule','ack'].includes(formType)||['reject','cancel'].includes(form.action)" maxlength="2000"/></label>
 <template v-if="formType==='action'&&form.action==='submit'"><label>处理结果<textarea v-model="form.result" required maxlength="4000"/></label><label>现场读数<textarea v-model="form.readings" maxlength="2000" placeholder="例如：温度、甲烷读数及单位"/></label></template>
 <template v-if="formType==='handbook'"><label>标题<input v-model="form.title" required maxlength="200"/></label><label>故障分类<input v-model="form.category" required maxlength="100"/></label><label>处置步骤<textarea v-model="form.steps" required maxlength="10000" rows="6"/></label><label>复核要点<textarea v-model="form.reviewPoints"/></label><label>参考来源<input v-model="form.source" maxlength="500"/></label></template>
 <template v-if="formType==='plan'"><label>巡检周期（小时）<input v-model.number="form.periodHours" type="number" min="1" max="8760" required/></label><label>巡检点位（可多选）<select v-model="form.nodeIds" multiple required><option v-for="n in nodes.filter(n=>n.area_id===Number(form!.areaId))" :value="n.id">{{n.code}} · {{n.location}}</option></select></label><label>检查项目<textarea v-model="form.checkItems" required maxlength="2000"/></label></template>
 <template v-if="formType==='patrolResult'"><label>检查结果与现场读数<textarea v-model="form.result" required maxlength="4000"/></label><label class="work-check"><input v-model="form.abnormal" type="checkbox"/>发现异常，自动建立待派发工单</label></template>
 <p v-if="error" class="work-error" role="alert">{{error}}</p><button class="primary wide" :disabled="busy">{{busy?'提交中…':'确认保存'}}</button>
 </form></div>
</div>
</template>
